int Font_FindCjk(uint16_t code)
{
    int lo = 0;
    int hi = (int)FONT_CJK_COUNT - 1;

    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (font_cjk_code[mid] == code) {
            return mid;
        } else if (font_cjk_code[mid] < code) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

